  "is_atomic": true,
  "atomic_questions": [
    "Is there any constraint on the total number of units that can be sold over the entire six-month period, or can you sell as many units as you want as long as you have the inventory?"
  ],
  "rationale": "The response asks a single clarification question regarding sales constraints, presented as a binary choice between having a limit or unlimited sales (subject to inventory)."
}
